local function C_5()
	local script = LMG2L["LocalScript2_5"];
	-- LocalScript dalam button "hide show"	

	local button = script.Parent	
	local uis = game:GetService("UserInputService")	

	local dragging = false	
	local dragInput, startPos, startButtonPos	

	local function update(input)	
		local delta = input.Position - startPos	
		button.Position = UDim2.new(	
			startButtonPos.X.Scale,	
			startButtonPos.X.Offset + delta.X,	
			startButtonPos.Y.Scale,	
			startButtonPos.Y.Offset + delta.Y	
		)	
	end	

	local function onInputBegan(input)	
		if input.UserInputType == Enum.UserInputType.MouseButton1 or	
		   input.UserInputType == Enum.UserInputType.Touch then	
			dragging = true	
			startPos = input.Position	
			startButtonPos = button.Position	

			input.Changed:Connect(function()	
				if input.UserInputState == Enum.UserInputState.End then	
					dragging = false	
				end	
			end)	
		end	
	end	

	local function onInputChanged(input)	
		if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then	
			update(input)	
		end	
	end	

	button.InputBegan:Connect(onInputBegan)	
	button.InputChanged:Connect(onInputChanged)	
end;
task.spawn(C_5);
