local function C_10()
	local script = LMG2L["console results_10"];
	local root = script.Parent	
	local consoleFrame = root:FindFirstChild("console", true)	

	if not consoleFrame then	
		warn("Frame 'console' tak jumpa")	
		return	
	end	

	consoleFrame.BackgroundColor3 = Color3.fromRGB(0,0,0)	

	-- SCROLL AREA	
	local logBox = Instance.new("ScrollingFrame")	
	logBox.Parent = consoleFrame	
	logBox.BackgroundTransparency = 1	
	logBox.Size = UDim2.new(1,0,1,0)	
	logBox.CanvasSize = UDim2.new(0,0,0,0)	
	logBox.ScrollBarThickness = 6	
	logBox.ScrollingDirection = Enum.ScrollingDirection.XY -- scroll semua arah	

	local layout = Instance.new("UIListLayout")	
	layout.Parent = logBox	
	layout.SortOrder = Enum.SortOrder.LayoutOrder	

	-- AUTO UPDATE CANVAS	
	layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()	
		logBox.CanvasSize = UDim2.new(	
			0,	
			layout.AbsoluteContentSize.X + 20,	
			0,	
			layout.AbsoluteContentSize.Y + 20	
		)	
	end)	

	-- ADD LOG FUNCTION	
	local function addLog(msg,color)	
		local text = Instance.new("TextLabel")	
		text.Parent = logBox	
		text.BackgroundTransparency = 1	
		text.Size = UDim2.new(0,1000,0,20) -- width besar supaya boleh scroll kanan	
		text.Font = Enum.Font.Code	
		text.TextXAlignment = Enum.TextXAlignment.Left	
		text.TextSize = 16	
		text.Text = tostring(msg)	
		text.TextColor3 = color	
	end	

	-- override print warn error	
	local oldPrint = print	
	local oldWarn = warn	

	print = function(...)	
		oldPrint(...)	
		addLog(table.concat({...}," "),Color3.fromRGB(0,255,0))	
	end	

	warn = function(...)	
		oldWarn(...)	
		addLog(table.concat({...}," "),Color3.fromRGB(255,170,0))	
	end	

	error = function(...)	
		addLog(table.concat({...}," "),Color3.fromRGB(255,0,0))	
	end	
end;
task.spawn(C_10);
