local function C_11()
	local script = LMG2L["requireding_11"];
	-- LocalScript	

	local root = script.Parent	

	-- cari button & textbox automatik	
	local executeButton = root:FindFirstChild("executeButton", true)	
	local inputBox = root:FindFirstChild("inputBox", true)	

	local playerGui = game.Players.LocalPlayer:WaitForChild("PlayerGui")	

	if not executeButton then	
		warn("executeButton not found")	
		return	
	end	

	if not inputBox then	
		warn("inputBox not found")	
		return	
	end	

	executeButton.MouseButton1Click:Connect(function()	

		local scriptText = inputBox.Text	
		local assetId = scriptText:match("require%s*%(?%s*(%d+)%s*%)?")	

		if assetId then	

			local success, result = pcall(function()	

				local objects = game:GetObjects("rbxassetid://" .. assetId)	
				local obj = objects[1]	

				if obj then	
					obj.Parent = playerGui	

					if obj:IsA("ModuleScript") then	
						local ok, err = pcall(function()	
							require(obj)	
						end)	

						if not ok then	
							warn("Error require module:", err)	
						end	
					end	
				end	
			end)	

			if not success then	
				warn("Error load asset:", result)	
			end	
		end	
	end)	
end;
task.spawn(C_11);
